@doc """
    check(material)

Ask MUESLI whether the material's parameters are admissible.

Worth calling once after construction: an inadmissible parameter set is otherwise only noticed
much later, when a stress evaluation returns nonsense.

# Returns
`true` if the material is consistent.
"""
function check end

@doc """
    print(material)

Print MUESLI's own description of the material — its type and derived constants — to `stdout`.
"""
function print end

@doc """
    createMaterialPoint(material)

Create a material point for `material`.

Equivalent to calling the matching `...MP` constructor, e.g. `ElasticIsotropicMP(material)`.

# See Also
- [`updateCurrentState`](@ref MuesliMaterials.updateCurrentState)
"""
function createMaterialPoint end

@doc """
    ElasticIsotropicMaterial(E::Real, ν::Real, ρ::Real = 1.0)
    ElasticIsotropicMaterial(props::MaterialProperties)

Linear isotropic elasticity, MUESLI's `elasticIsotropicMaterial`.

# Arguments
- `E`: Young's modulus
- `ν`: Poisson's ratio
- `ρ`: density (default: `1.0`)
- `props`: alternatively a property map carrying `"young"` and `"poisson"`

# Details
The response is ``\\sigma = 2\\mu\\varepsilon + \\lambda\\,\\mathrm{tr}(\\varepsilon)\\,I``,
with the Lamé parameters derived from `E` and `ν`.

# Examples
```julia
material = ElasticIsotropicMaterial(210000.0, 0.3)
mp = ElasticIsotropicMP(material)
```

# See Also
- [`ElasticIsotropicMP`](@ref)
"""
ElasticIsotropicMaterial

@doc """
    ElasticAnisotropicMaterial(c::AbstractVector, ρ::Real = 1.0)
    ElasticAnisotropicMaterial(props::MaterialProperties)

Fully anisotropic linear elasticity.

`c` must hold the **21** independent constants of the elasticity tensor; any other length
raises an error.
"""
ElasticAnisotropicMaterial

@doc """
    ElasticOrthotropicMaterial(c::AbstractVector, ρ::Real = 1.0)
    ElasticOrthotropicMaterial(props::MaterialProperties)

Orthotropic linear elasticity.

`c` must hold **9** constants; any other length raises an error.
"""
ElasticOrthotropicMaterial

@doc """
    ElasticTransverselyisotropicMaterial(c::AbstractVector, ρ::Real = 1.0)
    ElasticTransverselyisotropicMaterial(props::MaterialProperties)

Transversely isotropic linear elasticity.

`c` must hold **6** constants; any other length raises an error.
"""
ElasticTransverselyisotropicMaterial

@doc """
    SplasticMaterial(E, ν, ρ, Hiso, Hkine, yield, xalpha, plasticityType::String)
