@doc """
    NeoHookeMaterial(props::MaterialProperties)

Compressible neo-Hookean hyperelasticity, MUESLI's `neohookeanMaterial`.

Build it from a property map carrying `"young"` and `"poisson"`. At ``F = I`` the material is
stress free and stores no energy.

# Examples
```julia
props = MaterialProperties()
setProperty!(props, "young", 210000.0)
setProperty!(props, "poisson", 0.3)

material = NeoHookeMaterial(props)
mp = NeoHookeMP(material)
```

# See Also
- [`NeoHookeMP`](@ref)
"""
NeoHookeMaterial

@doc """
    SVKMaterial(props::MaterialProperties)

Saint Venant-Kirchhoff hyperelasticity — the linear relation between the Green-Lagrange strain
and the second Piola-Kirchhoff stress.
"""
SVKMaterial

@doc """
    YeohMaterial(props::MaterialProperties)

Yeoh hyperelasticity, an invariant-based rubber model.
"""
YeohMaterial

@doc """
    MooneyMaterial(props::MaterialProperties)

Mooney-Rivlin hyperelasticity.
"""
MooneyMaterial

@doc """
    ArrudaBoyceMaterial(props::MaterialProperties)

Arruda-Boyce eight-chain hyperelasticity.
"""
ArrudaBoyceMaterial

@doc """
    FplasticMaterial(props::MaterialProperties)

Finite strain plasticity.
"""
FplasticMaterial

# ---------------------------------------------------------------------------------------
# Material points
# ---------------------------------------------------------------------------------------

@doc """
    ElasticIsotropicMP(material::ElasticIsotropicMaterial)

The material point of a linear isotropic elastic material.

Carries the state at one location. Push a strain into it with
[`updateCurrentState`](@ref MuesliMaterials.updateCurrentState), then read stresses, tangents
and energies out of it.
"""
ElasticIsotropicMP

@doc """
    NeoHookeMP(material::NeoHookeMaterial)

The material point of a neo-Hookean material. Takes the deformation gradient rather than a
strain tensor.
"""
NeoHookeMP

@doc """
    SVKMP(material::SVKMaterial)

The material point of a Saint Venant-Kirchhoff material.
"""
SVKMP

@doc """
    YeohMP(material::YeohMaterial)

The material point of a Yeoh material.
"""
YeohMP

@doc """
    updateCurrentState(mp, t::Real, strain::Istensor)
    updateCurrentState(mp, t::Real, F::Itensor)

Set the trial state of the material point at time `t`.

# Details
Small strain points take the linearised strain as an [`Istensor`](@ref); finite strain points
take the deformation gradient as a general [`Itensor`](@ref).

This sets the *current* state only. A solver iterating on a step calls this repeatedly, then
either accepts the step with
[`commitCurrentState`](@ref MuesliMaterials.commitCurrentState) or discards it with
[`resetCurrentState`](@ref MuesliMaterials.resetCurrentState).

There is no bang, because the call advances the point's own history rather than filling an
argument.
"""
function updateCurrentState end

@doc """
    commitCurrentState(mp)

Accept the current state as converged.

# See Also
- [`resetCurrentState`](@ref MuesliMaterials.resetCurrentState)
"""
function commitCurrentState end

@doc """
    resetCurrentState(mp)

Discard the current state and return to the last converged one.
"""
function resetCurrentState end

@doc """
    setConvergedState(mp, t::Real, strain)

Set the converged state directly, bypassing the trial state.

Useful when restoring a material point from stored history. Plastic, viscoelastic and
viscoplastic points take additional internal variables; see their MUESLI documentation.
"""
function setConvergedState end

@doc """
    stress!(mp, σ::Istensor)

Compute the Cauchy stress of a small strain material point into `σ`.

# Examples
```julia
σ = Istensor()
stress!(mp, σ)
```
"""
function stress! end

@doc """
    deviatoricStress!(mp, s::Istensor)

Compute the deviatoric part of the stress into `s`.
"""
function deviatoricStress! end

@doc """
    pressure(mp)

The pressure, i.e. minus one third of the trace of the stress.
"""
function pressure end

@doc """
    tangentTensor!(mp, ℂ::Itensor4)

Compute the small strain tangent ``\\partial\\sigma/\\partial\\varepsilon`` into `ℂ`.

For a linear isotropic material this is
``\\mathbb{C}_{ijkl} = \\lambda\\delta_{ij}\\delta_{kl} +
\\mu(\\delta_{ik}\\delta_{jl} + \\delta_{il}\\delta_{jk})``, and contracting it with the strain
reproduces the stress.
"""
function tangentTensor! end

@doc """
    firstPiolaKirchhoffStress!(mp, P::Itensor)

Compute the first Piola-Kirchhoff stress ``P`` into `P`.

``P`` is **not** symmetric, hence the general [`Itensor`](@ref). It relates to the second
Piola-Kirchhoff stress by ``P = FS``.
"""
function firstPiolaKirchhoffStress! end

@doc """
    secondPiolaKirchhoffStress!(mp, S::Istensor)

Compute the symmetric second Piola-Kirchhoff stress ``S`` into `S`.

``S`` is unaffected by a rigid rotation of the deformation, which makes it the convenient
measure for a material-frame formulation.
"""
function secondPiolaKirchhoffStress! end

@doc """
    KirchhoffStress!(mp, τ::Istensor)

Compute the Kirchhoff stress ``\\tau = J\\sigma = PF^{T}`` into `τ`.
"""
function KirchhoffStress! end

@doc """
    CauchyStress!(mp, σ::Istensor)

Compute the Cauchy (true) stress ``\\sigma`` into `σ`.
"""
function CauchyStress! end

@doc """
    firstPiolaKirchhoffStressNumerical!(mp, P::Itensor)

Compute the first Piola-Kirchhoff stress by numerically differentiating the stored energy.

Slower and less accurate than
[`firstPiolaKirchhoffStress!`](@ref MuesliMaterials.firstPiolaKirchhoffStress!), and meant for
checking: if the analytic and numerical stresses disagree, the model is wired up wrongly.
"""
function firstPiolaKirchhoffStressNumerical! end

@doc """
    secondPiolaKirchhoffStressNumerical!(mp, S::Istensor)

Compute the second Piola-Kirchhoff stress by numerical differentiation of the stored energy.

!!! warning "Broken upstream"
    This does not currently produce a usable result. MUESLI's
    `finiteStrainMP::secondPiolaKirchhoffStressNumerical` assigns a general `itensor` into the
    symmetric `istensor` output, which never reaches the symmetric tensor's storage, so `S`
    keeps whatever was already in memory. It is intermittent — sometimes the memory happens to
    look plausible — which makes it worse than a hard failure.

    Use [`firstPiolaKirchhoffStressNumerical!`](@ref MuesliMaterials.firstPiolaKirchhoffStressNumerical!),
    which is correct, and convert with ``S = F^{-1}P`` if you need the second measure.
"""
function secondPiolaKirchhoffStressNumerical! end

